script:
// Mercury: gate the custom "Delivered" Task status.
//
// "Delivered" is added to Task.status by a Property Setter, which is DocType-wide -
// Frappe Select options are metadata, so an option cannot be offered to only some
// records. This script removes it from the dropdown unless the task's company has
// ticked "Allow Delivered Task Status".
//
// THIS IS COSMETIC. The real enforcement is server-side in mercury/task_status.py
// (doc_events -> Task.validate), because a REST call, a Data Import or
// frappe.db.set_value never runs this file. Do not delete that hook and rely on this.

const MERCURY_DELIVERED = "Delivered";

function mercury_apply_delivered_option(frm) {
    const field = frm.get_field("status");
    if (!field) return;

    const meta_field = frappe.get_meta("Task").fields.find(
        (f) => f.fieldname === "status"
    );
    const base = (meta_field.options || "").split("\n");

    const show = () => {
        field.df.options = base.join("\n");
        frm.refresh_field("status");
    };

    const hide = () => {
        // Never strip the option when the saved record already uses it - the control
        // would render blank and an ordinary save would silently clear the status.
        if (frm.doc.status === MERCURY_DELIVERED) return show();
        field.df.options = base
            .filter((o) => o !== MERCURY_DELIVERED)
            .join("\n");
        frm.refresh_field("status");
    };

    if (!frm.doc.company && !frm.doc.project) return hide();

    frappe.call({
        method: "mercury.task_status.is_delivered_allowed",
        args: { company: frm.doc.company, project: frm.doc.project },
        callback: (r) => (r.message ? show() : hide()),
    });
}

frappe.ui.form.on("Task", {
    refresh: mercury_apply_delivered_option,
    project: mercury_apply_delivered_option,
    company: mercury_apply_delivered_option,
});

// Shows the RTM approval workflow as a stepper across the top of the Sales Order,
// with the current state highlighted - instead of only a status pill in the header.
//
// Draft -> Submittal Under Customer Review -> RTM Approved, with Revision Requested
// shown as the branch it actually is (it loops back to review, it is not step 3).
//
// Everything is wrapped in try/catch: a cosmetic banner must never block a form.

frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        try {
            render_rtm_stepper(frm);
        } catch (e) {
            console.error("RTM stepper:", e);
        }
    },
});

function render_rtm_stepper(frm) {
    $(".mercury-rtm-stepper").remove();
    const state = frm.doc.workflow_state;
    if (!state) return;

    const MAIN = ["Draft", "Submittal Under Customer Review", "RTM Approved"];
    const SHORT = {
        "Draft": "Draft",
        "Submittal Under Customer Review": "Under Customer Review",
        "RTM Approved": "RTM Approved",
    };
    const revising = state === "Revision Requested";
    // While revising, the order has been through review and is on its way back
    let current = MAIN.indexOf(state);
    if (revising) current = 1;

    const steps = MAIN.map((s, i) => {
        const done = i < current;
        const active = i === current && !revising;
        const cls = done ? "done" : active ? "active" : "todo";
        const mark = done ? "&#10003;" : i + 1;
        return `<div class="mrs-step ${cls}">
                    <div class="mrs-dot">${mark}</div>
                    <div class="mrs-label">${frappe.utils.escape_html(SHORT[s])}</div>
                </div>`;
    }).join('<div class="mrs-line"></div>');

    const banner = revising
        ? `<div class="mrs-branch">&#8630; Revision Requested &mdash; back with engineering,
             returns to Under Customer Review</div>`
        : "";

    const html = `
    <div class="mercury-rtm-stepper">
      <style>
        .mercury-rtm-stepper { padding: 14px 16px 12px; margin-bottom: 10px;
            background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e2e6ea);
            border-radius: 8px; }
        .mrs-row { display: table; width: 100%; table-layout: fixed; }
        .mrs-step { display: table-cell; text-align: center; vertical-align: top; width: 30%; }
        .mrs-line { display: table-cell; vertical-align: middle; height: 2px;
            background: var(--border-color, #e2e6ea); width: 5%; }
        .mrs-dot { width: 26px; height: 26px; line-height: 26px; border-radius: 50%;
            margin: 0 auto 6px; font-size: 12px; font-weight: 600;
            background: var(--control-bg, #f4f5f6); color: var(--text-muted, #8d99a6);
            border: 2px solid var(--border-color, #e2e6ea); }
        .mrs-label { font-size: 12px; color: var(--text-muted, #8d99a6); }
        .mrs-step.done .mrs-dot { background: #2e7d32; border-color: #2e7d32; color: #fff; }
        .mrs-step.done .mrs-label { color: var(--text-color); }
        .mrs-step.active .mrs-dot { background: #1f4e79; border-color: #1f4e79; color: #fff;
            box-shadow: 0 0 0 4px rgba(31,78,121,.15); }
        .mrs-step.active .mrs-label { color: var(--text-color); font-weight: 600; }
        .mrs-branch { margin-top: 10px; text-align: center; font-size: 12px; font-weight: 600;
            color: #b26a00; background: #fff6e5; border: 1px solid #f0dcb0;
            border-radius: 6px; padding: 5px 10px; }
      </style>
      <div class="mrs-row">${steps}</div>
      ${banner}
    </div>`;

    // sits directly above the form body, under the page head
    $(frm.layout.wrapper).find(".form-layout").before(html);
}
